          "text": "1 g orally up to four times daily as needed for pain, for at most 2 days; maximum 4 g/day",
          "route": {
            "text": "oral"
          },
          "asNeededBoolean": true,
          "timing": {
            "repeat": {
              "frequency": 4,
              "period": 1,
              "periodUnit": "d"
            }
          },
          "doseAndRate": [
            {
              "doseQuantity": {
                "value": 1,
                "unit": "g"
              }
            }
          ],
          "maxDosePerPeriod": {
            "numerator": {
              "value": 4,
              "unit": "g"
            },
            "denominator": {
              "value": 1,
              "unit": "day"
            }
          }
        }
      ]
    }
  ]
}

